const templates = Object.keys(allCopy).filter((source) => /\{\w+\}/.test(source)).map((source) => {
  const names: string[] = [];
  const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\\\{(\w+)\\\}/g, (_match, name: string) => { names.push(name); return "(.+?)"; });
  return { source, names, pattern: new RegExp(`^${escaped}$`) };
});

export const supplementalSources = [...Object.keys(allCopy), ...Object.keys(aliases)];

export function coverageText(locale: Locale, source: string): string | undefined {
  if (locale === "en") return source;
  const direct = allCopy[aliases[source] ?? source]?.[localeIndex[locale]];
  if (direct) return direct;
  for (const template of templates) {
    const match = template.pattern.exec(source);
    if (!match) continue;
    const values = Object.fromEntries(template.names.map((name, index) => [name, match[index + 1]]));
    return allCopy[template.source][localeIndex[locale]].replace(/\{(\w+)\}/g, (placeholder, name: string) => values[name] ?? placeholder);
  }
  return undefined;
}
